        const src = ac.createBufferSource(); src.buffer = brown;
        const f = ac.createBiquadFilter(); f.type = 'lowpass'; f.frequency.setValueAtTime(900, t); f.frequency.exponentialRampToValueAtTime(120, t + 2.5);
        const gn = g(0);
