    P.AN = `<image href="${ANETT_IMG}" width="64" height="64" preserveAspectRatio="xMidYMid slice"/>`;
    P.BW = `<image href="${ANNA_IMG}" width="64" height="64" preserveAspectRatio="xMidYMid slice"/>`; // Bu Anna: ilustrasi potret dari pemilik game
    P.KK = `<image href="${MAMED_IMG}" width="64" height="64" preserveAspectRatio="xMidYMid slice"/>`; // Mamed: ilustrasi potret dari pemilik game
    P.RK = P.AN;
    return (id) => P[id] ? `<svg viewBox="0 0 64 64" aria-hidden="true">${P[id]}</svg>` : null;
