    if (e.target === ui.lever) return;
    const k = e.key.toLowerCase();
    if (k === 'arrowup' || k === 'w') { e.preventDefault(); setNotch(S.notch + 1); }
    else if (k === 'arrowdown' || k === 's') { e.preventDefault(); setNotch(S.notch - 1); }
