    const h0 = BEND ? bAt(BEND.H, x0) : 0, ch = Math.cos(h0), sh = Math.sin(h0);
    const S0 = BEND ? bAt(BEND.S, x0) : 0, C0 = BEND ? bAt(BEND.C, x0) : 0;
