    lampL(W * 0.255, st.doors === 'open', '#f2c94c', 'PINTU'); lampL(W * 0.33, st.notch > 0, '#5fd08a', 'TRAKSI'); lampL(W * 0.41, st.notch < 0, '#f2c94c', 'REM'); lampL(W * 0.475, !!st.slip, '#ef5b4c', 'SELIP');
