          const cl = Math.sin(i * 0.7 + lay * 2) * 0.5 + 0.5, bw = W * (0.026 + hash(i * 1.7 + lay) * 0.026) * sz, bh = H * (0.07 + 0.24 * cl * (0.5 + 0.5 * hash(i * 2.9 + lay))) * sz;
