    c.lineTo(fx - 1.6 * u, top); c.quadraticCurveTo(fx - 0.3 * u, top + 0.1 * u, fx - 0.05 * u, top + 1.4 * u); c.lineTo(fx, base - 0.6 * u); c.quadraticCurveTo(fx, base - 0.3 * u, fx - 0.3 * u, base - 0.3 * u); c.closePath(); c.fill();
    // lekuk roda
