    c.fillStyle = wg; c.beginPath();
    c.moveTo(x0 + 0.5 * u, top + 0.4 * u); c.lineTo(fx - 1.7 * u, top + 0.4 * u); c.quadraticCurveTo(fx - 0.55 * u, top + 0.45 * u, fx - 0.25 * u, top + 1.9 * u);
