      const off = pcOf(V) * 0.05 - (V.pan || 0), sx0 = V.sunX !== undefined ? sunPos(V).x : W * 0.8;
      ridgePath(V, 0.05, gy - 8, gy * 0.42, (u) => 0.18 + 0.1 * Math.sin(u * 0.004) + 0.06 * Math.sin(u * 0.011), V.night ? '#262a48' : mix('#8a76a0', '#9aa6c0', p));
