    const d = LANDMARKS[id], el = $('postcard'); if (!d || !el) return;
    $('pcTitle').textContent = d.name; $('pcSub').textContent = d.sub; $('pcCount').textContent = `Kartu pos ${n} dari ${LM_IDS.length}`;
    const cv2 = $('pcArt'), c2 = cv2.getContext('2d');
