        c.beginPath(); c.moveTo(sx2 - sr * 2, yh + 1); c.lineTo(sx2 + sr * 2, yh + 1); c.moveTo(sx2, yh + 1 - sr); c.lineTo(sx2, yh + 1 + sr); c.stroke();
