    const flick = speed > 3 ? Math.pow(Math.max(0, Math.sin(wx / 6.5)), 10) * clamp(speed / 25, 0, 1) * 0.35 : 0;
    const K = k * (0.9 + 0.1 * Math.sin(tt * 0.7)) * (1 - flick);
