    c.lineWidth = 6 * u; [[0, 'rgba(255,120,120,'], [6, 'rgba(255,220,120,'], [12, 'rgba(120,220,255,']].forEach(([dr, col]) => { c.strokeStyle = col + (0.025 * K).toFixed(3) + ')'; c.beginPath(); c.arc(sun.x, sun.y, W * 0.16 + dr * u, 0, 7); c.stroke(); });
