      const seed = Math.floor(wx / 140); if (hash(seed * 2.9) < 0.45) continue;
      const t = (2.5 + hash(seed) * 2) / rows, sx = at(X(wx + hash(seed * 4.1) * 40), t), base = rowY(t), sc = (0.5 + Math.pow(t, 1.55) * 1.6) * ppm * 0.5;
