      const R = [[-14, 13], [-17.5, 21.6], [-15.6, 20.6], [-11, 16.3], [-6.8, 19.4], [-6.0, 19.9], [-5.2, 19.1], [0, 16.9], [5.2, 19.1], [6.0, 19.9], [6.8, 19.4], [11, 16.3], [15.6, 20.6], [17.5, 21.6], [14, 13]];
