      c.strokeStyle = 'rgba(255,255,255,0.12)'; c.lineWidth = 1; c.beginPath(); for (let m = 0; m < m1 - m0; m += 0.5) { c.moveTo(x0 + m * ppm, top); c.lineTo(x0 + m * ppm, top + 0.32 * ppm); } c.stroke();
