        c.save(); c.translate(sx, gy - 2.9 * ppm); c.rotate(pm > 0 ? -0.35 : pm < 0 ? 0.35 : 0);
        c.fillStyle = '#f4f1e8'; c.fillRect(-1.1 * ppm, -0.45 * ppm, 2.2 * ppm, 0.9 * ppm);
        c.fillStyle = '#111'; c.textAlign = 'center'; c.textBaseline = 'middle';
