    const top = Y(1.72), bot = Y(0.36);
    const g = c.createLinearGradient(0, top, 0, bot); g.addColorStop(0, '#4f545c'); g.addColorStop(0.55, '#30343a'); g.addColorStop(1, '#1b1e22');
    c.fillStyle = g; c.fillRect(x, top, w, bot - top);
